    "title": "Joshua 4: Twelve Memorial Stones at Gilgal",
    "subtitle": "Lifting twelve stones from the Jordan’s center so future children ask, \"What do these stones mean?\"",
    "summaryHook": "Lifting twelve stones from the Jordan’s center so future children ask, \"What do these stones mean?\"",
    "bigPictureText": "Ensuring the miracle isn’t forgotten, one representative from every tribe carries a stone onto dry shore to build a family storytelling monument at Gilgal.",
