        "bookId": "JOS",
        "bookName": "Joshua",
        "chapterNumber": 6,
        "verseNumber": 13,
        "text": "The seven priests bearing the seven trumpets of rams’ horns in front of Yahweh’s ark went on continually, and blew the trumpets. The armed men went in front of them. The rear guard came after Yahweh’s ark. The trumpets sounded as they went.",
        "translation": "WEB",
        "illustrationId": "ill-jos-6",
